import React, { lazy, useEffect } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { getCurrentUser } from '../../../../../../libs/getCurrentUser'
import { getPostsByUser } from '../../../../../../services/user/actions/getPostsByUser'
import { UserPostCard } from '../../../../../societies'
import { getUserPostErrorMessage, getUserPostStatus, selectAllUserPost } from '../../../../../../services/post/reducers/userPostSlice'
const Loader = lazy(() => import('../../../../../../components/loader/Loader'))

const PostFeed = ({profileOptions, userId}) => {
  const dispatch = useDispatch()
  const currentUser = getCurrentUser()
  const userPost = useSelector(selectAllUserPost)
  const userPostStatus = useSelector(getUserPostStatus)
  const userPostErrorMessage = useSelector(getUserPostErrorMessage)

  const postsByUser = () => {
    try{
      const payload = {
        options: {
          method: "GET",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${currentUser.userToken}
            `,
          },
        },
        _id: userId ? userId : currentUser.userUid

      }
      dispatch(getPostsByUser(payload))
    }

    catch(error){
      console.log(error)
    }
  }

  useEffect(() => {
      postsByUser()
  }, [dispatch, userId])

  if(userPostStatus === "loading"){
    return <Loader text={"Loading"} isSmallLoader={true}/>
  }

  return (
    <article className="post-feed">
      {userPost?.map(post => {
        return <UserPostCard options={profileOptions} key={post._id} posts={post} />
      })}
    </article>
  )
}

export default PostFeed
