import React, { lazy, useEffect } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { getCurrentUser } from '../../../../../../libs/getCurrentUser'
import { UserPostCard } from '../../../../../societies'
import { getPostUserUpvoted } from '../../../../../../services/post/actions/interactions/getPostUserUpvoted'
import { getUserUpvotedPostErrorMessage, getUserUpvotedPostStatus, selectAllUpvotedPosts } from '../../../../../../services/post/reducers/upvoteSlice'
const Loader = lazy(() => import('../../../../../../components/loader/Loader'))

const Upvote = ({profileOptions, userId}) => {
  const userUpvotedPosts = useSelector(selectAllUpvotedPosts)
  const userUpvotedPostStatus = useSelector(getUserUpvotedPostStatus)
  const userUpvotedPostErrorMessage = useSelector(getUserUpvotedPostErrorMessage)
  const dispatch = useDispatch()
  const currentUser = getCurrentUser()
 
  const upvotedPostsByUser = () => {
    const payload = {
      options: {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${currentUser.userToken}
          `,
        },
      },
      userUid: userId ? userId : currentUser.userUid
    }

    dispatch(getPostUserUpvoted(payload))
  }

  useEffect(() => {
    upvotedPostsByUser()

    return () => upvotedPostsByUser
  }, [dispatch, userId])

  if(userUpvotedPostStatus === "loading"){
    return <Loader text={"Loading"} isSmallLoader={true}/>
  }

  return (
    <article className="upvote-feed">
      {userUpvotedPosts.map(post => {
          return <UserPostCard options={profileOptions} key={post._id} posts={post} />
      })}
    </article>
  )
}

export default Upvote
